	}
}

// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchClientIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	proxy := MatchRemoteIP{
		Ranges: m.Ranges,
		cidrs:  m.cidrs,
		zones:  m.zones,
		logger: m.logger,
	}
	err := proxy.UnmarshalCaddyfile(d)
	m.Ranges = proxy.Ranges
	m.cidrs = proxy.cidrs
	m.zones = proxy.zones
	return err
}

